    internal static string? SafeGetCardDescription(CardModel card, PileType pile = PileType.Hand)
    {
        try { return StripRichTextTags(card.GetDescriptionForPile(pile)).Replace("\n", " "); }
        catch { return SafeGetText(() => card.Description)?.Replace("\n", " "); }
    }

    /// <summary>
    /// The state a relic reports about itself (Normal, Active, Disabled), by name. Relics that work once per fight
    /// (Vambrace, Unsettling Lamp) or once per run (Lizard Tail) show whether they are spent through it.
    /// Read by reflection because the property is not part of the surface this mod is built against.
    /// </summary>
    internal static string? RelicStatusName(object relic)
    {
        try
        {
            for (var type = relic.GetType(); type != null; type = type.BaseType)
            {
                var property = type.GetProperty("Status",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public |
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly);
                if (property != null)
                    return property.GetValue(relic)?.ToString();
            }
        }
        catch { }
        return null;
    }

    /// <summary>
    /// Which card types Rainbow Ring has seen this turn, as bits: 1 Attack, 2 Skill, 4 Power. The relic keeps the counts
    /// in private fields and its status only shows that it has already paid out, so without this a state read in the
    /// middle of a turn cannot tell how close it is. Null for any other relic (or if the fields are not there).
    /// </summary>
    internal static int? RelicTypesPlayed(object relic)
    {
        try
        {
            if (relic.GetType().Name != "RainbowRing") return null;
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic;
            int Count(string field)
            {
                var info = relic.GetType().GetField(field, flags);
                return info?.GetValue(relic) is int n ? n : throw new MissingFieldException(field);
            }
            return (Count("_attacksPlayedThisTurn") > 0 ? 1 : 0) |
                   (Count("_skillsPlayedThisTurn") > 0 ? 2 : 0) |
                   (Count("_powersPlayedThisTurn") > 0 ? 4 : 0);
        }
        catch { return null; }
    }

    /// <summary>
    /// Whether a once-per-fight relic has already done its job, for the relics whose Status never says so: Permafrost
    /// (block on the first Power), Ruined Helmet (the one doubled Strength), Music Box, Throwing Axe and Pael's Eye (the extra turn). Null for any other relic.
    /// </summary>
    internal static bool? RelicSpent(object relic)
    {
        try
        {
            string? field = relic.GetType().Name switch
            {
                "Permafrost" => "_activatedThisCombat",
                "RuinedHelmet" => "_usedThisCombat",
                "CentennialPuzzle" => "_usedThisCombat",
                "DemonTongue" => "_triggeredThisTurn",
                "MusicBox" => "_wasUsedThisTurn",
                "ThrowingAxe" => "_usedThisCombat",
                "PaelsEye" => "_usedThisCombat",
                _ => null
            };
            if (field == null) return null;
            var info = relic.GetType().GetField(field,
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public |
                System.Reflection.BindingFlags.NonPublic);
            return info?.GetValue(relic) as bool?;
        }
        catch { return null; }
    }

    /// <summary>Adds the extra, relic-specific fields to a relic's entry in the state.</summary>
    internal static void AddRelicExtras(Dictionary<string, object?> entry, object relic)
    {
        var types = RelicTypesPlayed(relic);
        if (types != null) entry["types_played"] = types;
        var spent = RelicSpent(relic);
        if (spent != null) entry["spent"] = spent;
    }

    internal static string? SafeGetText(Func<object?> getter)
    {
        try
        {
            var result = getter();
            if (result == null) return null;
            // If it's a LocString, call GetFormattedText
            if (result is MegaCrit.Sts2.Core.Localization.LocString locString)
                return StripRichTextTags(locString.GetFormattedText());
            return result.ToString();
        }
        catch { return null; }
    }

    internal static string StripRichTextTags(string text)
    {
        // Remove BBCode-style tags like [color=red], [/color], etc.
        // Special case: [img]res://path/to/file.png[/img] → [file.png]
        var sb = new StringBuilder();
        int i = 0;
        while (i < text.Length)
        {
            if (text[i] == '[')
            {
                // Check for [img]...[/img] pattern
                if (text.AsSpan(i).StartsWith("[img]"))
                {
                    int contentStart = i + 5; // length of "[img]"
                    int closeTag = text.IndexOf("[/img]", contentStart, StringComparison.Ordinal);
                    if (closeTag >= 0)
                    {
                        string path = text[contentStart..closeTag];
                        int lastSlash = path.LastIndexOf('/');
                        string filename = lastSlash >= 0 ? path[(lastSlash + 1)..] : path;
                        sb.Append('[').Append(filename).Append(']');
                        i = closeTag + 6; // length of "[/img]"
                        continue;
                    }
                }

                int end = text.IndexOf(']', i);
                if (end >= 0) { i = end + 1; continue; }
            }
            sb.Append(text[i]);
            i++;
        }
        return sb.ToString();
    }
    internal static List<Dictionary<string, object?>> BuildHoverTips(IEnumerable<IHoverTip> tips)
    {
        var result = new List<Dictionary<string, object?>>();
        try
        {
            var seen = new HashSet<string>();
            foreach (var tip in IHoverTip.RemoveDupes(tips))
            {
                try
                {
                    string? title = null;
                    string? description = null;

                    if (tip is HoverTip ht)
                    {
                        title = ht.Title != null ? StripRichTextTags(ht.Title) : null;
                        description = StripRichTextTags(ht.Description);
                    }
                    else if (tip is CardHoverTip cardTip)
                    {
                        title = SafeGetText(() => cardTip.Card.Title);
                        description = SafeGetCardDescription(cardTip.Card);
                    }

                    if (title == null && description == null) continue;

                    string key = title ?? description!;
                    if (!seen.Add(key)) continue;

                    result.Add(new Dictionary<string, object?>
                    {
                        ["name"] = title,
                        ["description"] = description
                    });
                }
                catch { /* skip individual tip on error */ }
            }
        }
        catch { /* return partial results */ }
        return result;
    }
    internal static Dictionary<string, object?> BuildPlayerState(Player player)
    {
        var state = new Dictionary<string, object?>();
        var creature = player.Creature;
        var combatState = player.PlayerCombatState;

        state["character"] = SafeGetText(() => player.Character.Title);
        state["hp"] = creature.CurrentHp;
        state["max_hp"] = creature.MaxHp;
        state["block"] = creature.Block;

        if (combatState != null)
        {
            state["energy"] = combatState.Energy;
            state["max_energy"] = combatState.MaxEnergy;

            // Stars (The Regent's resource, conditionally shown)
            if (player.Character.ShouldAlwaysShowStarCounter || combatState.Stars > 0)
            {
                state["stars"] = combatState.Stars;
            }

            // Osty (The Necrobinder's pet): absent until summoned, hp 0 once it has died
            var osty = player.Osty;
            if (osty != null)
            {
                state["osty"] = new Dictionary<string, object?>
                {
                    ["hp"] = osty.CurrentHp,
                    ["max_hp"] = osty.MaxHp,
                    ["alive"] = osty.IsAlive
                };
            }

            // Hand
            var hand = new List<Dictionary<string, object?>>();
            int cardIndex = 0;
            foreach (var card in combatState.Hand.Cards)
            {
                hand.Add(BuildCardState(card, cardIndex));
                cardIndex++;
            }
            state["hand"] = hand;

            // Pile counts
            state["draw_pile_count"] = combatState.DrawPile.Cards.Count;
            state["discard_pile_count"] = combatState.DiscardPile.Cards.Count;
            state["exhaust_pile_count"] = combatState.ExhaustPile.Cards.Count;

            // Pile contents
            state["draw_pile"] = BuildPileCardList(combatState.DrawPile.Cards, PileType.Draw);
            state["discard_pile"] = BuildPileCardList(combatState.DiscardPile.Cards, PileType.Discard);
            state["exhaust_pile"] = BuildPileCardList(combatState.ExhaustPile.Cards, PileType.Exhaust);

            // Orbs
            if (combatState.OrbQueue.Capacity > 0)
            {
                var orbs = new List<Dictionary<string, object?>>();
                foreach (var orb in combatState.OrbQueue.Orbs)
                {
                    // Populate SmartDescription placeholders with Focus-modified values,
                    // mirroring OrbModel.HoverTips getter (OrbModel.cs:92-94)
                    string? description = SafeGetText(() =>
                    {
                        var desc = orb.SmartDescription;
                        desc.Add("energyPrefix", orb.Owner.Character.CardPool.Title);
                        desc.Add("Passive", orb.PassiveVal);
                        desc.Add("Evoke", orb.EvokeVal);
                        return desc;
                    });
                    orbs.Add(new Dictionary<string, object?>
                    {
                        ["id"] = orb.Id.Entry,
                        ["name"] = SafeGetText(() => orb.Title),
                        ["description"] = description,
                        ["passive_val"] = orb.PassiveVal,
                        ["evoke_val"] = orb.EvokeVal,
                        ["keywords"] = BuildHoverTips(orb.HoverTips)
                    });
                }
                state["orbs"] = orbs;
                state["orb_slots"] = combatState.OrbQueue.Capacity;
                state["orb_empty_slots"] = combatState.OrbQueue.Capacity - combatState.OrbQueue.Orbs.Count;
            }
        }

        state["gold"] = player.Gold;

        // Powers (status effects)
        state["status"] = BuildPowersState(creature);

        // Relics
        var relics = new List<Dictionary<string, object?>>();
        foreach (var relic in player.Relics)
        {
            var entry = new Dictionary<string, object?>
            {
                ["id"] = relic.Id.Entry,
                ["name"] = SafeGetText(() => relic.Title),
                ["description"] = SafeGetText(() => relic.DynamicDescription),
                ["counter"] = relic.ShowCounter ? relic.DisplayAmount : null,
                ["status"] = RelicStatusName(relic),
                ["keywords"] = BuildHoverTips(relic.HoverTipsExcludingRelic)
            };
            AddRelicExtras(entry, relic);
            relics.Add(entry);
        }
        state["relics"] = relics;

        // Potions
        var potions = new List<Dictionary<string, object?>>();
        int slotIndex = 0;
        foreach (var potion in player.PotionSlots)
        {
            if (potion != null)
            {
                potions.Add(new Dictionary<string, object?>
                {
                    ["id"] = potion.Id.Entry,
                    ["name"] = SafeGetText(() => potion.Title),
                    ["description"] = SafeGetText(() => potion.DynamicDescription),
                    ["slot"] = slotIndex,
                    ["can_use_in_combat"] = potion.Usage == PotionUsage.CombatOnly || potion.Usage == PotionUsage.AnyTime,
                    ["target_type"] = potion.TargetType.ToString(),
                    ["keywords"] = BuildHoverTips(potion.ExtraHoverTips)
                });
            }
            slotIndex++;
        }
        state["potions"] = potions;
        state["potion_slots"] = player.PotionSlots.Count;
        state["open_potion_slots"] = player.PotionSlots.Count(s => s == null);

        // The whole run deck (not the combat piles): safe to read on every screen.
        state["deck"] = BuildDeckList(player);

        return state;
    }

    internal static List<Dictionary<string, object?>> BuildDeckList(Player player)
    {
        var deck = new List<Dictionary<string, object?>>();
        int index = 0;
        foreach (var card in player.Deck.Cards)
        {
            try
            {
                deck.Add(BuildDeckCardState(card, index));
            }
            catch
            {
                deck.Add(new Dictionary<string, object?>
                {
                    ["index"] = index,
                    ["id"] = card.Id.Entry,
                    ["name"] = SafeGetText(() => card.Title)
                });
            }
            index++;
        }
        return deck;
    }

    // Lean on purpose: no CanPlay, description or hover tips, so polling a big deck stays cheap.
    internal static Dictionary<string, object?> BuildDeckCardState(CardModel card, int index)
    {
        string costDisplay = card.EnergyCost.CostsX ? "X" : card.EnergyCost.GetAmountToSpend().ToString();

        string? starCostDisplay = null;
        if (card.HasStarCostX)
            starCostDisplay = "X";
        else if (card.CurrentStarCost >= 0)
            starCostDisplay = card.GetStarCostWithModifiers().ToString();

        return new Dictionary<string, object?>
        {
            ["index"] = index,
            ["id"] = card.Id.Entry,
            ["name"] = card.Title,
            ["type"] = card.Type.ToString(),
            ["rarity"] = card.Rarity.ToString(),
            ["cost"] = costDisplay,
            ["star_cost"] = starCostDisplay,
            ["is_upgraded"] = card.IsUpgraded,
            ["upgrade_level"] = card.CurrentUpgradeLevel,
            ["can_upgrade"] = card.IsUpgradable,
            ["removable"] = card.IsRemovable,
            ["floor_added"] = card.FloorAddedToDeck,
            ["enchantment"] = BuildEnchantment(card)
        };
    }

    internal static Dictionary<string, object?> BuildCardState(CardModel card, int index)
    {
        string costDisplay;
        if (card.EnergyCost.CostsX)
            costDisplay = "X";
        else
        {
            int cost = card.EnergyCost.GetAmountToSpend();
            costDisplay = cost.ToString();
        }

        card.CanPlay(out var unplayableReason, out _);

        // Star cost (The Regent's cards; CanonicalStarCost >= 0 means card has a star cost)
        string? starCostDisplay = null;
        if (card.HasStarCostX)
            starCostDisplay = "X";
        else if (card.CurrentStarCost >= 0)
            starCostDisplay = card.GetStarCostWithModifiers().ToString();

        return new Dictionary<string, object?>
        {
            ["index"] = index,
            ["id"] = card.Id.Entry,
            ["name"] = card.Title,
            ["type"] = card.Type.ToString(),
            ["cost"] = costDisplay,
            ["star_cost"] = starCostDisplay,
            ["description"] = SafeGetCardDescription(card),
            ["target_type"] = card.TargetType.ToString(),
            ["can_play"] = unplayableReason == UnplayableReason.None,
            ["unplayable_reason"] = unplayableReason != UnplayableReason.None ? unplayableReason.ToString() : null,
            ["is_upgraded"] = card.IsUpgraded,
            // true for a card made during this combat (no DeckVersion): the Thieving Hopper cannot steal it
            ["generated"] = card.DeckVersion == null,
            // null, or {"id": "SHARP", "amount": 2}: the hover tips only carry the localized text
            ["enchantment"] = BuildEnchantment(card),
            ["keywords"] = BuildHoverTips(card.HoverTips)
        };
    }

    internal static Dictionary<string, object?>? BuildEnchantment(CardModel card)
    {
        try
        {
            var enchantment = card.Enchantment;
            if (enchantment == null) return null;
            return new Dictionary<string, object?>
            {
                ["id"] = enchantment.Id.Entry,
                ["amount"] = (int)enchantment.Amount
            };
        }
        catch { return null; }
    }

    internal static List<Dictionary<string, object?>> BuildPileCardList(IEnumerable<CardModel> cards, PileType pile)
    {
        // Full card info (id, cost, type, upgrade, target...) like the hand, so the simulator can load the piles.
        // The description is the pile's own: it does not include Strength or Weak the way a hand card's does.
        var list = new List<Dictionary<string, object?>>();
        int index = 0;
        foreach (var card in cards)
        {
            Dictionary<string, object?> entry;
            try
            {
                entry = BuildCardState(card, index);
                entry["description"] = SafeGetCardDescription(card, pile);
            }
            catch
            {
                entry = new Dictionary<string, object?>
                {
                    ["index"] = index,
                    ["id"] = card.Id.Entry,
                    ["name"] = SafeGetText(() => card.Title),
                    ["description"] = SafeGetCardDescription(card, pile)
                };
            }
            list.Add(entry);
            index++;
        }
        return list;
    }

    internal static Dictionary<string, object?> BuildEnemyState(Creature creature, Dictionary<string, int> entityCounts)
    {
        var monster = creature.Monster;
        string baseId = monster?.Id.Entry ?? "unknown";

        // Generate entity_id like "jaw_worm_0"
        if (!entityCounts.TryGetValue(baseId, out int count))
            count = 0;
        entityCounts[baseId] = count + 1;
        string entityId = $"{baseId}_{count}";

        var state = new Dictionary<string, object?>
        {
            ["entity_id"] = entityId,
            ["combat_id"] = creature.CombatId,
            ["name"] = SafeGetText(() => monster?.Title),
            ["hp"] = creature.CurrentHp,
            ["max_hp"] = creature.MaxHp,
            ["block"] = creature.Block,
            ["status"] = BuildPowersState(creature)
        };

        // Intents
        if (monster?.NextMove is MoveState moveState)
        {
            // Exact move identity from the game's state machine (replaces label inference).
            state["move_id"] = moveState.StateId;
            state["follow_up_id"] = moveState.FollowUpState?.Id ?? moveState.FollowUpStateId;
            // Move history (branch states excluded by the game); includes the current move last.
            var moveLog = monster.MoveStateMachine?.StateLog;
            if (moveLog != null)
                state["move_log"] = moveLog.Select(m => m.Id).ToList();

            var intents = new List<Dictionary<string, object?>>();
            foreach (var intent in moveState.Intents)
            {
                var intentData = new Dictionary<string, object?>
                {
                    ["type"] = intent.IntentType.ToString()
                };
                if (intent is AttackIntent attack)
                {
                    // base_damage: move's raw damage, before Strength/Vulnerable/etc.
                    // damage/total_damage: game-computed final values, for cross-checking the sim.
                    try
                    {
                        var atkTargets = creature.CombatState?.PlayerCreatures;
                        intentData["base_damage"] = (int)(attack.DamageCalc?.Invoke() ?? 0m);
                        intentData["hits"] = attack.Repeats;
                        if (atkTargets != null)
                        {
                            intentData["damage"] = attack.GetSingleDamage(atkTargets, creature);
                            intentData["total_damage"] = attack.GetTotalDamage(atkTargets, creature);
                        }
                    }
                    catch { /* damage calc may fail for exotic intents */ }
                }
                try
                {
                    var targets = creature.CombatState?.PlayerCreatures;
                    if (targets != null)
                    {
                        string label = intent.GetIntentLabel(targets, creature).GetFormattedText();
                        intentData["label"] = StripRichTextTags(label);

                        var hoverTip = intent.GetHoverTip(targets, creature);
                        if (hoverTip.Title != null)
                            intentData["title"] = StripRichTextTags(hoverTip.Title);
                        if (hoverTip.Description != null)
                            intentData["description"] = StripRichTextTags(hoverTip.Description);
                    }
                }
                catch { /* intent label may fail for some types */ }
                intents.Add(intentData);
            }
            state["intents"] = intents;
        }

        return state;
    }
    internal static List<Dictionary<string, object?>> BuildPowersState(Creature creature)
    {
        var powers = new List<Dictionary<string, object?>>();
        foreach (var power in creature.Powers)
        {
            if (!power.IsVisible) continue;

            // HoverTips resolves all dynamic vars (Amount, DynamicVars, etc.)
            // The first tip is the power's own description; the rest are extra keywords
            var allTips = power.HoverTips.ToList();
            string? resolvedDesc = null;
            var extraTips = new List<IHoverTip>();
            foreach (var tip in allTips)
            {
                if (tip.Id == power.Id.ToString())
                {
                    // This is the power's own hover tip — extract its resolved description
                    if (tip is HoverTip ht)
                        resolvedDesc = StripRichTextTags(ht.Description);
                }
                else
                {
                    extraTips.Add(tip);
                }
            }
            // Fallback to raw SmartDescription if HoverTips extraction failed
            resolvedDesc ??= SafeGetText(() => power.SmartDescription);

            powers.Add(new Dictionary<string, object?>
            {
                ["id"] = power.Id.Entry,
                ["name"] = SafeGetText(() => power.Title),
                ["amount"] = power.DisplayAmount,
                ["type"] = power.Type.ToString(),
                ["description"] = resolvedDesc,
                ["keywords"] = BuildHoverTips(extraTips)
            });
        }
        return powers;
    }
